// Her kural resmi veya güvenilir bir kaynağa dayanır; sadece bilgi amaçlıdır.
import type { ExtraVisa } from './visa-access.ts';

export type UnlockRule = {
  holder: ExtraVisa;
  destination: string;
  effect: 'visa_free' | 'visa_on_arrival' | 'evisa';
  max_days: number | null;
  /** İngilizce kısa koşul (ör. "multiple-entry visa, used at least once"). */
  condition: string | null;
  /** Sadece bu pasaportlar için geçerliyse; null = vize gerektiren herkes. */
  nationalities: string[] | null;
  source: string;
  /** Geçici düzenlemelerde son geçerlilik günü (YYYY-AA-GG). */
  valid_until?: string | null;
};

